/**
 * Phase 5 (Generate Migration Tracks) contracts for the AGENTS.md Compliance
 * Audit of `apps/science-advantage/` (pilot).
 *
 * The audit's Phase 5 deliverable is the migration plan: 12 Measure tracks
 * (Tracks 0–12) that group the 45 finding IDs from `findings.md` into
 * actionable migration work. Per `test-strategy.md` §1 / §5, the contract is:
 *
 *   - Each track has a valid skeleton (`metadata.json` + `spec.md` +
 *     `plan.md`).
 *   - Each plan has ≤15 phase-level work units (`## Phase N:` headings).
 *   - Each track references the finding ID(s) it resolves.
 *
 * The SUT is the audit's `migration-tracks.md` artifact plus the 12 track
 * directories it points at (`measure/tracks/<id>/` for pending tracks,
 * `measure/archive/<id>/` for completed tracks). Tests are unit-level (no
 * DB, no Next.js server) and use the same filesystem access patterns as
 * the Phase 0–4 audit tests.
 *
 * Cross-check contract (Phase 5.5): the proposed tracks must also be
 * listed in `measure/tracks.md` under the "Pending Tracks — Audit Findings
 * (science-advantage, 2026-06-03)" sub-heading, so the registry stays in
 * sync with the audit's deliverables.
 *
 * State of the tests on 2026-06-05:
 *   - 5.1 (migration-tracks.md structure)        — GREEN.
 *   - 5.2 (track skeleton exists)                — GREEN (all 12).
 *   - 5.3 (≤15 phase-level tasks per plan)       — GREEN (max 15,
 *     `ci_typecheck_alignment_20260603`).
 *   - 5.4 (finding ID reference in skeleton)     — GREEN.
 *   - 5.5 (cross-check vs measure/tracks.md)     — GREEN for the 12
 *     proposed tracks; the section also lists 1 follow-up ("Audit Log
 *     Retention + DSAR Bulk Export") that is not in migration-tracks.md —
 *     this is allowed (follow-up tracks can be appended) and the test
 *     asserts the 12 are present without forbidding extras.
 *
 * Known sub-contract gaps documented in `measure/tech-debt.md`:
 *   - `audit_log_infrastructure_20260603` (Track 4) is marked `complete`
 *     in `metadata.json` and the `Pending Tracks — Audit Findings`
 *     section is marked `[x]`, but the directory is still under
 *     `measure/tracks/` rather than `measure/archive/`. Not asserted
 *     here (move is a track-completion chore, not a Phase 5 contract).
 *   - 4 metadata.json files have `estimated_tasks > 15` (zod: 18,
 *     domain: 24, observability: 16, ci: 17). The Phase 5 contract is
 *     about the actual plan phases, not the estimate, so this is not
 *     asserted.
 *
 * See: measure/tracks/agents_md_audit_science_advantage_20260603/test-strategy.md
 */
import fs from 'fs/promises';
import path from 'path';
import { execFileSync } from 'child_process';
import { describe, it, expect } from 'vitest';

const MONOREPO_ROOT = execFileSync('git', ['rev-parse', '--show-toplevel'], {
  encoding: 'utf-8',
}).trim();

const MIGRATION_TRACKS = path.join(
  MONOREPO_ROOT,
  'measure/audit-reports/science-advantage_20260603/migration-tracks.md',
);
const TRACKS_REGISTRY = path.join(MONOREPO_ROOT, 'measure/tracks.md');
const TRACKS_DIR = path.join(MONOREPO_ROOT, 'measure/tracks');
const ARCHIVE_DIR = path.join(MONOREPO_ROOT, 'measure/archive');

const PENDING_HEADING = 'Pending Tracks — Audit Findings (science-advantage, 2026-06-03)';

/**
 * The 12 tracks proposed in `migration-tracks.md` (Tracks 0–12) and their
 * declared severity. Track 0 is a protocol-level pre-audit chore (no
 * application code change); the other 11 are user-facing migration work.
 *
 * `trackId` is the directory name under `measure/tracks/` or
 * `measure/archive/`. Track 0's id is not inlined in `migration-tracks.md`
 * as `**Track ID:**` (it's a one-line summary); the others (1–12) are.
 * Hardcoding the mapping here keeps the parser focused on phase-level
 * validation rather than on title-to-id slugification.
 */
const PROPOSED_TRACKS: ReadonlyArray<{
  trackNum: number;
  trackId: string;
  severity: string;
  /** Finding IDs the track resolves, per `migration-tracks.md` `- **Resolves:**` line. */
  resolves: readonly string[];
}> = [
  {
    trackNum: 0,
    trackId: 'protocol_v1_1_graphdb_20260603',
    severity: 'Protocol',
    resolves: ['F-1003'],
  },
  {
    trackNum: 1,
    trackId: 'app_domain_migration_20260603',
    severity: 'Critical',
    resolves: ['F-305', 'F-203', 'F-208', 'F-306', 'F-307', 'F-405', 'F-701', 'F-702'],
  },
  {
    trackNum: 2,
    trackId: 'tenant_db_school_id_20260603',
    severity: 'Critical',
    resolves: ['F-501', 'F-502'],
  },
  {
    trackNum: 3,
    trackId: 'argon2id_password_20260603',
    severity: 'Critical',
    resolves: ['F-401', 'F-402', 'F-406'],
  },
  {
    trackNum: 4,
    trackId: 'audit_log_infrastructure_20260603',
    severity: 'Critical',
    resolves: ['F-404', 'F-901'],
  },
  {
    trackNum: 5,
    trackId: 'ai_adapter_package_20260603',
    severity: 'High',
    resolves: ['F-101', 'F-202'],
  },
  {
    trackNum: 6,
    trackId: 'storage_package_20260603',
    severity: 'High',
    resolves: ['F-102', 'F-703'],
  },
  {
    trackNum: 7,
    trackId: 'zod_boundary_hardening_20260603',
    severity: 'High',
    resolves: ['F-601', 'F-602', 'F-302', 'F-603', 'F-604', 'F-704'],
  },
  {
    trackNum: 8,
    trackId: 'domain_module_decomposition_20260603',
    severity: 'High',
    resolves: ['F-301', 'F-303', 'F-304', 'F-504', 'F-1101'],
  },
  {
    trackNum: 9,
    trackId: 'observability_stack_20260603',
    severity: 'Medium',
    resolves: ['F-902', 'F-903', 'F-904', 'F-905', 'F-906'],
  },
  {
    trackNum: 10,
    trackId: 'rate_limiter_v2_20260603',
    severity: 'Medium',
    resolves: ['F-403', 'F-407'],
  },
  {
    trackNum: 11,
    trackId: 'ci_typecheck_alignment_20260603',
    severity: 'High',
    resolves: ['F-1001', 'F-1002', 'F-1003', 'F-1204', 'F-1205'],
  },
  {
    trackNum: 12,
    trackId: 'housekeeping_batch_20260603',
    severity: 'Low',
    resolves: [
      'F-205',
      'F-503',
      'F-705',
      'F-1102',
      'F-1201',
      'F-1202',
      'F-1207',
      'F-1301',
      'F-1305',
      'F-1306',
    ],
  },
];

/**
 * Parse `migration-tracks.md` into one entry per `## Track N —` section,
 * capturing the track number, body, and the `**Track ID:**` value if
 * present (Track 0 omits it; the rest have it).
 */
async function parseMigrationTrackSections(): Promise<
  Array<{ trackNum: number; trackId: string | null; body: string }>
> {
  const contents = await fs.readFile(MIGRATION_TRACKS, 'utf-8');
  const sections: Array<{ trackNum: number; trackId: string | null; body: string }> = [];
  const lines = contents.split('\n');
  let current: { trackNum: number; trackId: string | null; body: string[] } | null = null;

  const flush = () => {
    if (current) {
      sections.push({
        trackNum: current.trackNum,
        trackId: current.trackId,
        body: current.body.join('\n'),
      });
    }
  };

  for (const line of lines) {
    const m = line.match(/^## Track (\d+) — /);
    if (m) {
      flush();
      current = {
        trackNum: Number(m[1]),
        trackId: null,
        body: [line],
      };
      continue;
    }
    if (current) {
      current.body.push(line);
      const idMatch = line.match(/^- \*\*Track ID:\*\*\s*`([^`]+)`/);
      if (idMatch) current.trackId = idMatch[1];
    }
  }
  flush();
  return sections;
}

/**
 * Find the directory for `trackId`. Completed tracks are moved to
 * `measure/archive/`; pending tracks stay in `measure/tracks/`. Returns
 * the absolute path of the existing directory, or `null` if neither
 * candidate exists.
 */
async function locateTrackDir(trackId: string): Promise<string | null> {
  for (const parent of [TRACKS_DIR, ARCHIVE_DIR]) {
    const candidate = path.join(parent, trackId);
    try {
      const stat = await fs.stat(candidate);
      if (stat.isDirectory()) return candidate;
    } catch {
      // not present; fall through
    }
  }
  return null;
}

/**
 * Count the number of `## Phase N:` top-level headings in a plan file.
 * This is the "≤15 tasks" contract from the test strategy: a track's plan
 * is a sequence of top-level phases, not a flat list of `- [ ]` items
 * (each phase typically has many sub-tasks). Tracks with 16+ phases are
 * too large to ship in a single PR; the protocol caps the count at 15.
 */
async function countTopLevelPhases(planPath: string): Promise<number> {
  const contents = await fs.readFile(planPath, 'utf-8');
  // Match `## Phase 0:`, `## Phase 1:`, etc. but NOT `### Phase 2a:`
  // (sub-phases are counted as part of the parent phase, not as their
  // own top-level work units).
  const matches = contents.match(/^## Phase \d+:/gm);
  return matches ? matches.length : 0;
}

describe('AGENTS.md Compliance Audit — science-advantage (Phase 5: Generate Migration Tracks)', () => {
  // ============================================================
  // 5.1 — migration-tracks.md exists and has 12 track sections
  // ============================================================
  describe('Phase 5.1 — migration-tracks.md structure', () => {
    /**
     * Per Phase 5 plan task 1: "Write `migration-tracks.md` — group
     * findings into tracks of ≤15 plan tasks". The deliverable is a
     * single Markdown file that introduces each proposed track as a
     * `## Track N — <title>` section. The plan text says "12 Measure
     * tracks" so 12 sections is the contract.
     *
     * GREEN today: the file exists, is non-empty, and contains 13
     * `## Track N —` sections (Tracks 0 through 12). Track 0 is the
     * pre-audit protocol chore and is counted as part of the 12-track
     * plan (the plan's own header says "12-Track Migration Plan" and
     * `## Overview` says "Track 0 is a protocol-refinement pre-audit
     * chore"). So the assertion is `>= 12` rather than `=== 12` to
     * accommodate the protocol chore being co-numbered.
     */
    it('migration-tracks.md exists at the expected path', async () => {
      const stat = await fs.stat(MIGRATION_TRACKS);
      expect(stat.isFile()).toBe(true);
    });

    it('migration-tracks.md is non-empty', async () => {
      const contents = await fs.readFile(MIGRATION_TRACKS, 'utf-8');
      expect(contents.length).toBeGreaterThan(0);
    });

    it('migration-tracks.md has a "## Track N —" section for every proposed track', async () => {
      const sections = await parseMigrationTrackSections();
      const declaredNumbers = sections.map((s) => s.trackNum).sort((a, b) => a - b);
      const expectedNumbers = PROPOSED_TRACKS.map((t) => t.trackNum).sort((a, b) => a - b);
      expect(
        declaredNumbers,
        `migration-tracks.md is missing track sections for: ${expectedNumbers
          .filter((n) => !declaredNumbers.includes(n))
          .join(', ')}`,
      ).toEqual(expectedNumbers);
    });
  });

  // ============================================================
  // 5.2 — Each proposed track has a valid skeleton
  // ============================================================
  describe('Phase 5.2 — Track skeleton (metadata.json + spec.md + plan.md)', () => {
    /**
     * Per Phase 5 plan task 2: "For each proposed track, write a
     * `metadata.json` + `spec.md` + `plan.md` skeleton". The
     * skeleton is the unit-level deliverable. A track without all
     * three files is not actionable from a Measure perspective
     * (no machine-readable status, no FR list, no plan checklist).
     *
     * Tracks are located under either `measure/tracks/<id>/` (pending)
     * or `measure/archive/<id>/` (completed and archived). GREEN today:
     * all 12 tracks have all three files in their respective directory.
     */
    it.each(PROPOSED_TRACKS)(
      'track $trackId (Track $trackNum) has metadata.json + spec.md + plan.md',
      async ({ trackId, trackNum }) => {
        const dir = await locateTrackDir(trackId);
        expect(
          dir,
          `track directory for ${trackId} (Track ${trackNum}) is missing from both measure/tracks/ and measure/archive/`,
        ).not.toBeNull();
        for (const file of ['metadata.json', 'spec.md', 'plan.md']) {
          const filePath = path.join(dir as string, file);
          const stat = await fs.stat(filePath);
          expect(
            stat.isFile(),
            `${trackId}/${file} is not a regular file`,
          ).toBe(true);
          expect(
            stat.size,
            `${trackId}/${file} is empty (size 0)`,
          ).toBeGreaterThan(0);
        }
      },
    );

    /**
     * Sub-contract: `metadata.json` is parseable JSON and has the
     * minimum fields (`track_id`, `type`, `description`). A track
     * with a broken `metadata.json` cannot be ingested by future
     * Measure tooling (status rollups, registry updates).
     */
    it.each(PROPOSED_TRACKS)(
      'track $trackId has a parseable metadata.json with track_id matching the directory name',
      async ({ trackId }) => {
        const dir = (await locateTrackDir(trackId)) as string;
        const meta = JSON.parse(await fs.readFile(path.join(dir, 'metadata.json'), 'utf-8'));
        expect(
          typeof meta.track_id,
          `${trackId}/metadata.json is missing 'track_id' field`,
        ).toBe('string');
        expect(
          meta.track_id,
          `${trackId}/metadata.json track_id ('${meta.track_id}') does not match the directory name`,
        ).toBe(trackId);
        expect(
          typeof meta.type,
          `${trackId}/metadata.json is missing 'type' field`,
        ).toBe('string');
        expect(
          typeof meta.description,
          `${trackId}/metadata.json is missing 'description' field`,
        ).toBe('string');
      },
    );
  });

  // ============================================================
  // 5.3 — Each plan has ≤15 phase-level work units
  // ============================================================
  describe('Phase 5.3 — Plan has ≤15 phase-level tasks', () => {
    /**
     * Per Phase 5 plan task 1 and `test-strategy.md` §1: "Track ≤15
     * tasks". A "task" here is a top-level `## Phase N:` section —
     * each phase is a self-contained work unit shippable in one PR.
     * Sub-phases (`### Phase 2a:`, `### Phase 2b:`, …) are part of
     * the parent phase, not their own top-level work unit.
     *
     * The cap of 15 is the protocol's PR-reviewability ceiling; tracks
     * with more phases should be split (e.g. Track 8 could become
     * `domain_module_decomposition` + `codecamp_module_split`).
     *
     * GREEN today (2026-06-05): every plan is ≤15 phases. The
     * maximum is `ci_typecheck_alignment_20260603` (Track 11) at
     * exactly 15 phases (0–14). One more phase on Track 11 would
     * breach the contract.
     */
    it.each(PROPOSED_TRACKS)(
      'track $trackId plan has ≤15 ## Phase N: sections',
      async ({ trackId, trackNum }) => {
        const dir = (await locateTrackDir(trackId)) as string;
        const phaseCount = await countTopLevelPhases(path.join(dir, 'plan.md'));
        expect(
          phaseCount,
          `${trackId} (Track ${trackNum}) plan has ${phaseCount} ## Phase N: sections; the test-strategy §1 contract caps tracks at 15. Split the track before adding more work.`,
        ).toBeLessThanOrEqual(15);
        // Sanity: every plan has at least Phase 0 (Setup) + Phase 1
        // (first real work) + a Closeout phase. Anything below 3 is
        // almost certainly missing a real plan.
        expect(
          phaseCount,
          `${trackId} (Track ${trackNum}) plan has only ${phaseCount} phases; expected at least 3 (Phase 0 + ≥1 work phase + Closeout).`,
        ).toBeGreaterThanOrEqual(3);
      },
    );
  });

  // ============================================================
  // 5.4 — Each track references the finding ID(s) it resolves
  // ============================================================
  describe('Phase 5.4 — Finding ID reference in skeleton', () => {
    /**
     * Per Phase 5 plan task 1: each track must group specific
     * findings from `findings.md` into a migration plan. The
     * binding is: the finding IDs listed in `migration-tracks.md`
     * `- **Resolves:**` for that track must be mentioned in the
     * track's `metadata.json` (description field) or `spec.md`
     * (Problem section). Otherwise the track is disconnected
     * from the audit and the reader cannot trace work back to a
     * finding.
     *
     * GREEN today: every track's `metadata.json` description
     * contains the `Resolves:` list verbatim (or close to it,
     * depending on whether the track notes "partial" or "(root)"
     * subsumptions).
     */
    it.each(PROPOSED_TRACKS)(
      'track $trackId metadata.json description references every finding it resolves',
      async ({ trackId, resolves }) => {
        const dir = (await locateTrackDir(trackId)) as string;
        const meta = JSON.parse(await fs.readFile(path.join(dir, 'metadata.json'), 'utf-8'));
        const description: string = meta.description ?? '';
        const missing = resolves.filter((f) => !description.includes(f));
        expect(
          missing,
          `${trackId}/metadata.json description is missing finding IDs: ${missing.join(', ')}. The description should reference every finding this track resolves.`,
        ).toEqual([]);
      },
    );

    /**
     * Sub-contract: the spec.md also references the resolved
     * findings. A track with finding IDs only in the description
     * but not in the spec makes the FR list unmoored from the
     * audit (the spec is the "why" and must cite the finding).
     *
     * Note: spec.md may include additional F-IDs beyond the
     * resolves list (e.g. related findings mentioned in the
     * Problem section). The contract is that all `resolves`
     * IDs are mentioned, not that the mentions are exclusive.
     */
    it.each(PROPOSED_TRACKS)(
      'track $trackId spec.md references every finding it resolves',
      async ({ trackId, resolves }) => {
        const dir = (await locateTrackDir(trackId)) as string;
        const spec = await fs.readFile(path.join(dir, 'spec.md'), 'utf-8');
        const missing = resolves.filter((f) => !spec.includes(f));
        expect(
          missing,
          `${trackId}/spec.md is missing finding IDs: ${missing.join(', ')}. Every resolved finding must be cited in the spec's Problem section.`,
        ).toEqual([]);
      },
    );
  });

  // ============================================================
  // 5.5 — Cross-check vs measure/tracks.md registry
  // ============================================================
  describe('Phase 5.5 — measure/tracks.md "Pending Tracks — Audit Findings" cross-check', () => {
    /**
     * Per Phase 5 plan task 3: "Add the proposed tracks to
     * `measure/tracks.md` under 'Pending Tracks — Audit Findings'".
     * The registry is the user-facing entry point; a track that
     * exists only in `migration-tracks.md` is invisible to anyone
     * scanning the registry.
     *
     * GREEN today: every proposed track is listed in the section.
     */
    it('measure/tracks.md has the "Pending Tracks — Audit Findings" sub-heading', async () => {
      const contents = await fs.readFile(TRACKS_REGISTRY, 'utf-8');
      expect(contents).toContain(PENDING_HEADING);
    });

    it.each(PROPOSED_TRACKS)(
      'track $trackId is listed in the "Pending Tracks — Audit Findings" section',
      async ({ trackId }) => {
        const contents = await fs.readFile(TRACKS_REGISTRY, 'utf-8');
        // Find the section; the section ends at the next `####`
        // heading or at the next `---` separator / `### ` heading
        // (whichever comes first).
        const startIdx = contents.indexOf(PENDING_HEADING);
        expect(
          startIdx,
          `measure/tracks.md is missing the "${PENDING_HEADING}" section`,
        ).toBeGreaterThanOrEqual(0);
        // Take everything from the section start to the next `####` heading
        // (the section is `####`; the next `####` is the next section).
        const tail = contents.slice(startIdx);
        const sectionEndMatch = tail.slice(PENDING_HEADING.length).match(/^####\s/m);
        const section = sectionEndMatch
          ? tail.slice(0, PENDING_HEADING.length + (sectionEndMatch.index ?? tail.length))
          : tail;
        expect(
          section.includes(trackId),
          `track ${trackId} is not listed under "${PENDING_HEADING}" in measure/tracks.md. Add an entry with a Link to ${trackId.startsWith('protocol_v1_1') || trackId.startsWith('app_domain') || trackId.startsWith('tenant_db') || trackId.startsWith('argon2id') || trackId.startsWith('ai_adapter') ? './archive/' : './tracks/'}${trackId}/`,
        ).toBe(true);
      },
    );

    /**
     * Sub-contract: the link in the section entry points to an
     * existing directory. A link to a missing directory is a
     * broken registry entry.
     *
     * GREEN today: all 12 link paths resolve to existing
     * directories. The link targets are `./tracks/<id>/` for
     * pending tracks and `./archive/<id>/` for archived ones;
     * the test resolves both forms via `locateTrackDir`.
     */
    it.each(PROPOSED_TRACKS)(
      'track $trackId link target in measure/tracks.md points to an existing directory',
      async ({ trackId }) => {
        const dir = await locateTrackDir(trackId);
        expect(
          dir,
          `track ${trackId} link in measure/tracks.md points to a directory that does not exist (neither measure/tracks/${trackId}/ nor measure/archive/${trackId}/ is on disk)`,
        ).not.toBeNull();
      },
    );
  });
});

/**
 * Phase 4 (Classify Findings) contracts for the AGENTS.md Compliance
 * Audit of `apps/science-advantage/` (pilot).
 *
 * Phase 4 of the audit protocol (§5 of
 * `measure/agents-md-audit-protocol.md`) is the "classify findings"
 * pass: for each static-FAIL recorded in `findings.md`, the auditor
 * must:
 *
 *   1. Classify the severity as Critical | High | Medium | Low per
 *      the rubric in the protocol's §Severity Scheme.
 *   2. Sort findings by severity (Critical → High → Medium → Low).
 *   3. Add a summary table at the top of `findings.md`.
 *   4. Add a row to `measure/tech-debt.md` for every Critical and
 *      High finding. Medium and Low findings are batched into a
 *      single row per app.
 *   5. Keep `measure/tech-debt.md` at ≤50 lines (per §13.2).
 *
 * Severity rubric (`measure/agents-md-audit-protocol.md` §Severity
 * Scheme, abbreviated):
 *
 *   - **Critical** — Architectural breach that defeats a core
 *     AGENTS.md guarantee (e.g. routes import `db` directly,
 *     bypassing the domain layer; direct SDK coupling to a
 *     provider; missing multi-tenant scoping on a query path).
 *     **Action:** Block new features in the affected app until a
 *     migration track exists.
 *   - **High** — Violation that will compound (e.g. 100+ files
 *     importing a provider SDK, no test coverage on a domain
 *     module, business logic in a Server Action).
 *     **Action:** Open a migration track in the next planning cycle.
 *   - **Medium** — Localized violation that does not compound in
 *     the short term (e.g. one file with raw SQL, one component
 *     with hardcoded English in a fully-localized app).
 *     **Action:** Batch into a quarterly cleanup track.
 *   - **Low** — Style, tooling, or documentation gap (e.g. missing
 *     JSDoc, ignoreBuildErrors still on, IDE config drift).
 *     **Action:** Triage when nearby code is touched.
 *
 * The test strategy (`test-strategy.md` §5) prescribes:
 *   - Unit: Severity rubric consistency.
 *   - Per-Phase Test Approach: Verify severity against rubric.
 *     Verify `tech-debt.md` ≤50 lines.
 *
 * Cross-phase edge cases relevant here (`test-strategy.md` §3):
 *   - #4 (severity by blast radius, not rule number) is a
 *     judgment call and is not asserted directly; the audit's
 *     chosen severities are pinned and the protocol's §Severity
 *     Scheme text remains the source of truth.
 *   - #5 (Findings ↔ tracks consistency) is a Phase 5 concern;
 *     this file asserts only the Phase 4 record structure.
 *   - #6 (Tech-debt ≤50 lines) is asserted in Phase 4.5 below.
 *
 * The SUT is the audit's `findings.md` artifact and the
 * `measure/tech-debt.md` registry. Tests are unit-level (no DB,
 * no Next.js server) and use the same filesystem access patterns
 * as the Phase 0–3 audit tests.
 *
 * State of the tests on 2026-06-05:
 *   - 4.1 (severity classification), 4.2 (summary table), 4.4
 *     (tech-debt line cap), 4.5 (audit rows) — GREEN today.
 *     These pin contracts that are already satisfied and serve as
 *     regression guards for any future re-sort / re-classification
 *     of `findings.md` or any future edit of `tech-debt.md`.
 *   - 4.3 (sort by severity) — RED today. The first FAIL in
 *     `findings.md` is F-101 (Medium); the first Critical appears
 *     much later (F-305). The audit protocol §5 step 5 says
 *     "Sort findings by severity. Add a summary table at the top",
 *     which is the only Phase 4 task whose contract is not yet
 *     met. The test will turn GREEN when the auditor re-orders
 *     the body so all Criticals appear before any non-Critical.
 *
 * See: measure/tracks/agents_md_audit_science_advantage_20260603/test-strategy.md
 */
import fs from 'fs/promises';
import path from 'path';
import { execFileSync } from 'child_process';
import { describe, it, expect } from 'vitest';

const MONOREPO_ROOT = execFileSync('git', ['rev-parse', '--show-toplevel'], {
  encoding: 'utf-8',
}).trim();
const FINDINGS = path.join(
  MONOREPO_ROOT,
  'measure/audit-reports/science-advantage_20260603/findings.md',
);
const TECH_DEBT = path.join(MONOREPO_ROOT, 'measure/tech-debt.md');

/**
 * Valid severities per the protocol's §Severity Scheme. Any FAIL
 * whose severity bullet uses a different word is a classification
 * contract violation; the test must flag the auditor.
 */
const VALID_SEVERITIES: readonly string[] = [
  'Critical',
  'High',
  'Medium',
  'Low',
];

/**
 * Severity rank for the sort-by-severity test. Lower rank = more
 * severe = should appear earlier in the file. The protocol requires
 * Critical before High before Medium before Low (per §5 step 5).
 */
const SEVERITY_RANK: Readonly<Record<string, number>> = {
  Critical: 0,
  High: 1,
  Medium: 2,
  Low: 3,
};

/**
 * Section heading regex. Matches:
 *   `### F-101: ...`
 *   `### F-1302-F-1304: ...`
 * But NOT:
 *   `### F-101 + F-102 bundled ...`  (no colon after the second F-id)
 *   `### Findings`                   (no F- prefix)
 *   `## Section 1 — ...`             (##, not ###)
 *
 * Same regex as Phase 3 (`audit-phase3-manual-review.test.ts`) so
 * the two test files agree on which sub-headings are FAILs.
 */
const HEADING_RE = /^### (F-\d+(?:-F-\d+)?):/;

/**
 * Severity bullet regex. Matches `- **Severity:** **Critical**`
 * and variants like
 * `- **Severity:** **High** (originally; subsumed under F-305)`.
 * The first bolded word is the severity.
 *
 * The `m` flag is required: the regex is matched against a
 * multi-line section body, and we need `^` to anchor to the
 * start of any line (not just the start of the body). Without
 * `m`, `^` only matches the heading line, so the severity
 * bullet is invisible to the parser and every FAIL appears to
 * be missing a severity.
 *
 * The em-dash sentinel used by PASS findings
 * (`- **Severity:** — (no finding)`) does NOT match `\w+`, so
 * PASS findings naturally fall out as "no severity" — which is
 * exactly the behavior we want, because PASS findings are
 * excluded from the FAIL classification test below.
 */
const SEVERITY_RE = /^- \*\*Severity:\*\*\s*\*\*(\w+)\*\*/m;

/**
 * Read findings.md and split it into sections keyed by F-XXX
 * heading. A section's body is the heading line plus everything
 * up to the next `### F-` heading (or end of file). Sub-headings
 * like `### F-101 + F-102 bundled ...` (no `:` immediately after
 * the second F-id) are absorbed into the previous section.
 */
async function parseFindingsSections(): Promise<
  Map<string, { body: string; severity: string | null }>
> {
  const contents = await fs.readFile(FINDINGS, 'utf-8');
  const sections = new Map<string, { body: string; severity: string | null }>();
  const lines = contents.split('\n');
  let currentId: string | null = null;
  let currentBuf: string[] = [];
  const flush = () => {
    if (currentId) {
      const body = currentBuf.join('\n');
      const sev = body.match(SEVERITY_RE)?.[1] ?? null;
      sections.set(currentId, { body, severity: sev });
    }
  };
  for (const line of lines) {
    const m = line.match(HEADING_RE);
    if (m) {
      flush();
      currentId = m[1];
      currentBuf = [line];
    } else if (currentId) {
      currentBuf.push(line);
    }
  }
  flush();
  return sections;
}

/**
 * Filter the section map down to FAILs that require a severity
 * classification. Excludes:
 *   - Range headings (F-1302–F-1304) — these are PASS entries.
 *   - Single-ID headings whose first line contains the literal
 *     "PASS" — covers F-1206.
 *   - Sections that have no severity bullet at all (a missing
 *     severity is itself a violation, but the Phase 4.1 test
 *     reports it explicitly via the `missing` list).
 */
function getFailIds(sections: Map<string, { body: string; severity: string | null }>): string[] {
  const out: string[] = [];
  for (const [id, { body }] of sections.entries()) {
    if (/-F-\d+$/.test(id)) continue; // F-1302-F-1304 style range
    const firstLine = body.split('\n')[0];
    if (/\bPASS\b/.test(firstLine)) continue;
    out.push(id);
  }
  return out;
}

describe('AGENTS.md Compliance Audit — science-advantage (Phase 4: Classify Findings)', () => {
  // ============================================================
  // 4.1 — Severity classification exists for every FAIL
  // ============================================================
  describe('Phase 4.1 — Severity classification', () => {
    /**
     * Per protocol §Severity Scheme, every FAIL must be classified
     * as Critical | High | Medium | Low. A missing or invalid
     * severity is a classification contract violation — the
     * downstream readers (Severity rollup table, Critical/High
     * rows in `tech-debt.md`) cannot be produced from incomplete
     * data.
     *
     * GREEN today: all FAILs in `findings.md` have a severity
     * line of the form `- **Severity:** **X**`. PASS findings
     * (F-1206, F-1302–F-1304) are excluded by `getFailIds()`.
     */
    it('every FAIL section in findings.md has a valid severity classification', async () => {
      const sections = await parseFindingsSections();
      const failIds = getFailIds(sections);
      expect(failIds.length, 'expected at least one FAIL section in findings.md').toBeGreaterThan(0);

      const missing: string[] = [];
      const invalid: { id: string; severity: string }[] = [];
      for (const id of failIds) {
        const { severity } = sections.get(id) ?? { severity: null };
        if (severity === null) {
          missing.push(id);
        } else if (!VALID_SEVERITIES.includes(severity)) {
          invalid.push({ id, severity });
        }
      }
      expect(
        missing,
        `these FAILs are missing a severity classification: ${missing.join(', ')}`,
      ).toEqual([]);
      expect(
        invalid,
        `these FAILs have an invalid severity (must be Critical | High | Medium | Low): ${JSON.stringify(invalid)}`,
      ).toEqual([]);
    });
  });

  // ============================================================
  // 4.2 — Severity rollup table exists at the top
  // ============================================================
  describe('Phase 4.2 — Severity rollup table at the top of findings.md', () => {
    /**
     * Per protocol §5 step 5: "Sort findings by severity. Add a
     * summary table at the top." The rollup table is the one-page
     * entry point for the audit: a reader should be able to skim
     * the first ~50 lines and see how many findings of each
     * severity exist before diving into the per-section FAILs.
     *
     * GREEN today: `findings.md` lines 24–32 contain a "Severity
     * rollup" table that names all four valid severities. The
     * "headline reclassification" preamble (F-305 umbrella) is
     * allowed above the table — it is part of the top-of-file
     * summary, not per-finding body.
     */
    it('findings.md has a severity rollup table with all 4 severities in the first 50 lines', async () => {
      const contents = await fs.readFile(FINDINGS, 'utf-8');
      const head = contents.split('\n').slice(0, 50).join('\n');
      expect(
        head,
        'severity rollup table header should appear in the first 50 lines of findings.md',
      ).toMatch(/\|.*Severity.*\|/);
      for (const sev of VALID_SEVERITIES) {
        expect(
          head,
          `severity rollup should mention "${sev}" in the first 50 lines`,
        ).toContain(sev);
      }
    });
  });

  // ============================================================
  // 4.3 — Findings sorted by severity (the only RED test)
  // ============================================================
  describe('Phase 4.3 — Findings sorted by severity (Critical → Low)', () => {
    /**
     * Per protocol §5 step 5: "Sort findings by severity. Add a
     * summary table at the top." The audit's findings.md is
     * currently organized by section (§1 Provider Neutrality,
     * §2 Package Boundaries, …, §13 Workflow). The first FAIL
     * in body order is F-101 (Medium). The first Critical
     * appears much later (F-305 in §3).
     *
     * This test pins the sort property: every Critical must
     * appear in the file before any non-Critical. The auditor
     * may satisfy this by reordering the body (e.g. a single
     * "Critical findings" block, then High, then Medium, then
     * Low) or by reordering within each section. Either
     * approach produces a `findings.md` that opens with the
     * most severe failures — which is the contract the protocol
     * is asking for.
     *
     * RED today (2026-06-05): the first FAIL is F-101 (Medium).
     * The test fails with a list of misplaced findings.
     */
    it('findings.md is sorted by severity (no non-Critical FAIL appears before any Critical)', async () => {
      const sections = await parseFindingsSections();
      const failIds = getFailIds(sections);
      expect(failIds.length, 'expected at least one FAIL section').toBeGreaterThan(0);

      // Build the ordered (id, severity) list for all FAILs.
      const order: { id: string; severity: string }[] = [];
      for (const id of failIds) {
        const { severity } = sections.get(id) ?? { severity: null };
        if (severity) order.push({ id, severity });
      }
      expect(order.length, 'every FAIL should have a severity (Phase 4.1 dependency)').toBe(order.length);

      // Property 1: the first FAIL in the body must be Critical.
      const first = order[0];
      expect(
        first.severity,
        `first FAIL in findings.md is ${first.id} (${first.severity}); the protocol §5 step 5 requires the most severe findings to appear first — re-sort so a Critical is the first FAIL.`,
      ).toBe('Critical');

      // Property 2: severity rank must be monotonically
      // non-decreasing. Any violation is a misplaced finding.
      const violations: { id: string; severity: string; prevId: string; prevSeverity: string }[] = [];
      let lastRank = -1;
      let lastId = '';
      let lastSev = '';
      for (const { id, severity } of order) {
        const rank = SEVERITY_RANK[severity] ?? 99;
        if (rank < lastRank) {
          violations.push({ id, severity, prevId: lastId, prevSeverity: lastSev });
        }
        lastRank = rank;
        lastId = id;
        lastSev = severity;
      }
      expect(
        violations,
        `findings are not sorted by severity (a less-severe finding appears earlier than a more-severe one): ${JSON.stringify(violations)}`,
      ).toEqual([]);
    });
  });

  // ============================================================
  // 4.4 — tech-debt.md line count cap
  // ============================================================
  describe('Phase 4.4 — tech-debt.md line count', () => {
    /**
     * Per protocol §13.2 / AGENTS.md §Tech Debt Registry:
     * `measure/tech-debt.md` is current and <50 lines. The cap
     * is a curation gate: if a future Phase 4 (or a future audit
     * re-run) is tempted to add a Critical/High row for every
     * finding, the cap forces a batch-or-merge decision before
     * the file becomes un-curated.
     *
     * GREEN today (2026-06-05): the file is 49 lines.
     */
    it('measure/tech-debt.md has ≤ 50 lines (per protocol §13.2)', async () => {
      const contents = await fs.readFile(TECH_DEBT, 'utf-8');
      const lines = contents.split('\n').length;
      expect(
        lines,
        'tech-debt.md should be ≤ 50 lines per protocol §13.2 / AGENTS.md §Tech Debt Registry',
      ).toBeLessThanOrEqual(50);
    });
  });

  // ============================================================
  // 4.5 — tech-debt.md has audit_20260603_* rows
  // ============================================================
  describe('Phase 4.5 — tech-debt.md has audit_20260603_* rows for the audit clusters', () => {
    /**
     * Per protocol §Severity Scheme / §13.2: "A row is added to
     * `measure/tech-debt.md` for every Critical and High finding.
     * Medium and Low findings are batched into a single row per
     * app." The science-advantage pilot produces 4 Critical
     * clusters (each rolled up to a single row) and 1 Medium/Low
     * batched row:
     *
     *   - audit_20260603_domain_bypass (F-305 umbrella)
     *   - audit_20260603_tenancy_gap   (F-501, F-502)
     *   - audit_20260603_argon2id_required (F-402, F-406)
     *   - audit_20260603_audit_log_missing (F-404, F-901)
     *   - audit_20260603_housekeeping_batch (Medium/Low batch)
     *
     * HIGH findings (F-203, F-208, F-306, F-307, F-405, F-701,
     * F-702) are subsumed under F-305 in the Critical row above;
     * F-601, F-1002, F-1204, F-1205 are High and currently
     * batched into `housekeeping_batch`. The test asserts the
     * 4 Critical cluster IDs + 1 batch ID are present; a future
     * split-out of Highs would add new `audit_20260603_*` row
     * IDs, which is allowed and the test would still pass.
     *
     * GREEN today (2026-06-05): all 5 row IDs are present
     * (4 Resolved Criticals + 1 Open Medium/Low batch).
     */
    it('tech-debt.md has audit_20260603_* rows for the 4 Critical clusters and 1 Medium/Low batch', async () => {
      const contents = await fs.readFile(TECH_DEBT, 'utf-8');
      const expectedRowIds = [
        'audit_20260603_domain_bypass',
        'audit_20260603_tenancy_gap',
        'audit_20260603_argon2id_required',
        'audit_20260603_audit_log_missing',
        'audit_20260603_housekeeping_batch',
      ];
      const missing: string[] = [];
      for (const id of expectedRowIds) {
        if (!contents.includes(id)) missing.push(id);
      }
      expect(
        missing,
        `these audit_20260603_* rows are missing from tech-debt.md: ${missing.join(', ')}`,
      ).toEqual([]);
    });
  });
});

/**
 * Phase 0 setup contracts for the AGENTS.md Compliance Audit of
 * `apps/science-advantage/` (pilot).
 *
 * The audit protocol's §14 Pre-audit Preconditions require:
 *   14.1 `build-graph stats ./graph.db` reports `Total files > 0`.
 *   14.2 `graph.db` mtime is within the last 24 hours.
 *   14.3 `scripts/ci/check-graph-db.sh` exists and is executable.
 *
 * The Phase 0 plan adds two more preconditions that are not in §14
 * but are checked here so the audit is reproducible:
 *   - The audit-report directory exists and is non-empty.
 *   - The audited app's working tree matches the branch tip
 *     (no uncommitted or untracked drift that would invalidate the
 *     build-graph results).
 *
 * These tests are unit-level: they do not require a database, build
 * the science-advantage app, or spawn a Next.js server. They shell out
 * to `build-graph` and `git` for verification.
 *
 * See: measure/tracks/agents_md_audit_science_advantage_20260603/test-strategy.md
 */
import fs from 'fs/promises';
import path from 'path';
import { execFileSync } from 'child_process';
import { describe, it, expect } from 'vitest';

/**
 * Resolve the monorepo root via git so this test is robust to moves of
 * the file within the tree. Falls back to a relative walk-up if git is
 * not on PATH (CI without git → fail loudly).
 */
const MONOREPO_ROOT = execFileSync('git', ['rev-parse', '--show-toplevel'], {
  encoding: 'utf-8',
}).trim();
const GRAPH_DB = path.join(MONOREPO_ROOT, 'graph.db');
const AUDIT_REPORT_DIR = path.join(
  MONOREPO_ROOT,
  'measure/audit-reports/science-advantage_20260603',
);
const SCIENCE_ADVANTAGE_DIR = path.join(MONOREPO_ROOT, 'apps/science-advantage');
const CHECK_GRAPH_DB_SCRIPT = path.join(
  MONOREPO_ROOT,
  'scripts/ci/check-graph-db.sh',
);
const MAX_GRAPH_DB_AGE_MS = 24 * 60 * 60 * 1000;

function runCaptured(command: string, args: string[]): string {
  return execFileSync(command, args, { cwd: MONOREPO_ROOT, encoding: 'utf-8' }).trim();
}

describe('AGENTS.md Compliance Audit — science-advantage (Phase 0: Setup)', () => {
  describe('Protocol §14.1 — graph.db is populated', () => {
    it('graph.db exists at the monorepo root', async () => {
      const stat = await fs.stat(GRAPH_DB);
      expect(stat.isFile()).toBe(true);
    });

    it('build-graph stats reports Total files > 0', () => {
      const output = runCaptured('build-graph', ['stats', GRAPH_DB]);
      const match = output.match(/Total files:\s*(\d+)/);
      expect(match).not.toBeNull();
      const total = Number(match![1]);
      expect(total).toBeGreaterThan(0);
    });
  });

  describe('Protocol §14.2 — graph.db is fresh (<24h)', () => {
    it('graph.db mtime is within the last 24 hours', async () => {
      const stat = await fs.stat(GRAPH_DB);
      const ageMs = Date.now() - stat.mtime.getTime();
      expect(ageMs).toBeGreaterThanOrEqual(0);
      expect(ageMs).toBeLessThanOrEqual(MAX_GRAPH_DB_AGE_MS);
    });
  });

  describe('Protocol §14.3 — graph.db CI gate exists', () => {
    it('scripts/ci/check-graph-db.sh exists', async () => {
      const stat = await fs.stat(CHECK_GRAPH_DB_SCRIPT);
      expect(stat.isFile()).toBe(true);
    });

    it('scripts/ci/check-graph-db.sh is executable', async () => {
      const stat = await fs.stat(CHECK_GRAPH_DB_SCRIPT);
      // Owner-execute bit (0o100) is sufficient — CI runs as the same uid.
      expect(stat.mode & 0o100).toBeGreaterThan(0);
    });
  });

  describe('Phase 0 Task 1 — audit report directory exists', () => {
    it('measure/audit-reports/science-advantage_20260603/ is a directory', async () => {
      const stat = await fs.stat(AUDIT_REPORT_DIR);
      expect(stat.isDirectory()).toBe(true);
    });

    it('the audit report directory contains at least one artifact', async () => {
      const entries = await fs.readdir(AUDIT_REPORT_DIR);
      expect(entries.length).toBeGreaterThan(0);
    });
  });

  describe('Phase 0 Task 3 — apps/science-advantage/ matches main', () => {
    it('working tree has no uncommitted changes under apps/science-advantage/', () => {
      const porcelain = runCaptured('git', [
        'status',
        '--porcelain',
        'apps/science-advantage/',
      ]);
      expect(porcelain).toBe('');
    });

    it('apps/science-advantage/ exists at the expected path', async () => {
      const stat = await fs.stat(SCIENCE_ADVANTAGE_DIR);
      expect(stat.isDirectory()).toBe(true);
    });
  });
});

